from django.utils import timezone


def revoke_imported_consents(apps, schema_editor):
    """An imported (AppFolio) e-delivery flag is not consent. Each person whose current
    record is an imported consent gets a new postal record revoking it; the board sees them
    in the to-do list until each owner consents in HomeOA."""
    Pref = apps.get_model("registry", "NoticePreference")
    Person = apps.get_model("registry", "Person")
    for person in Person.objects.all():
        current = Pref.objects.filter(person=person).order_by("-recorded_at", "-pk").first()
        if current is None or current.source != "import" or not current.e_delivery_consent:
            continue
        Pref.objects.create(
            association_id=current.association_id,
            person=person,
            delivery="postal",
            e_delivery_consent=False,
            email="",
            source="system",
            note="AppFolio e-delivery: yes",
            revoked_at=timezone.now(),
            revoke_reason="import",
        )


